import sys, heapq
input = lambda : sys.stdin.readline().rstrip()

def calc(A):
	(q, s, ans) = ([], 0, 0)
	for i in A:
		s += i
		heapq.heappush(q, i)
		while s < 0:
			s -= 2 * heapq.heappop(q)
			ans += 1
	return ans

def solve():
	(n, m) = map(int, input().split())
	A = list(map(int, input().split()))
	return calc(list(map(lambda a: -a, A[m - 1:0:-1]))) + calc(A[m:])
T = int(input())
for i in range(T):
	print(solve())
